import { supabase } from './supabase'
import { fetchAllRows } from './fetchAll'
export { HYGIENE_LOCATIONS, DAY_LABELS, HYGIENE_DAYS, shortLocation } from './constants'

// day_num and utilizationPct are GENERATED by the database — read, never written.
// Computing the percentage in one place means the table, the totals and any
// export can never disagree about it.
function toJS(row) {
  return {
    id:        row.id,
    location:  row.location,
    workDate:  row.work_date,
    hours:     row.hours,
    available: row.available != null ? Number(row.available) : 0,
    utilized:  row.utilized  != null ? Number(row.utilized)  : 0,
    notes:     row.notes,
    dayNum:    row.day_num,
    pct:       row.utilization_pct != null ? Number(row.utilization_pct) : null,
    createdBy: row.created_by,
  }
}

function toDB(entry) {
  return {
    location:  entry.location || null,
    work_date: entry.workDate || null,
    hours:     entry.hours    || null,
    available: Number(entry.available) || 0,
    utilized:  Number(entry.utilized)  || 0,
    notes:     entry.notes    || null,
  }
}

export async function getHygieneRows() {
  const rows = await fetchAllRows(() =>
    supabase
      .from('hygiene_utilization')
      .select('*')
      .order('work_date', { ascending: false })
      .order('id', { ascending: true })
  )
  return rows.map(toJS)
}

export async function saveHygieneRow(entry) {
  const row = toDB(entry)
  if (entry.id) {
    const { data, error } = await supabase
      .from('hygiene_utilization').update(row).eq('id', entry.id).select().single()
    if (error) throw error
    return toJS(data)
  }
  const { data, error } = await supabase
    .from('hygiene_utilization').insert(row).select().single()
  if (error) throw error
  return toJS(data)
}

export async function deleteHygieneRow(id) {
  const { error } = await supabase.from('hygiene_utilization').delete().eq('id', id)
  if (error) throw error
}

/**
 * Roll rows up into totals.
 *
 * The overall percentage is total-utilized over total-available — NOT the mean
 * of each row's percentage. Averaging percentages weights a 2-hour day the same
 * as a 9-hour one and quietly reports the wrong number.
 */
export function summarise(rows) {
  const available = rows.reduce((s, r) => s + (Number(r.available) || 0), 0)
  const utilized  = rows.reduce((s, r) => s + (Number(r.utilized)  || 0), 0)
  return {
    available,
    utilized,
    pct: available > 0 ? (utilized / available) * 100 : null,
  }
}

// Import writes go through upsert on (location, work_date) — the same pair the
// unique index enforces. Re-importing a corrected month therefore UPDATES the
// existing days instead of failing the whole batch on a duplicate key.
//
// Chunked because a single statement returning thousands of rows runs into the
// same server row cap that truncates reads.
const UPSERT_CHUNK = 500

export async function bulkUpsertHygieneRows(entries) {
  // Postgres refuses an upsert that touches the same key twice in one
  // statement, so a file listing a location/date pair more than once must be
  // collapsed first. Last occurrence wins — it is the most recent correction.
  const byKey = new Map()
  for (const e of entries) byKey.set(`${e.location}|${e.workDate}`, e)
  const deduped = [...byKey.values()]

  const saved = []
  for (let i = 0; i < deduped.length; i += UPSERT_CHUNK) {
    const chunk = deduped.slice(i, i + UPSERT_CHUNK).map(toDB)
    const { data, error } = await supabase
      .from('hygiene_utilization')
      .upsert(chunk, { onConflict: 'location,work_date' })
      .select()
    if (error) throw error
    saved.push(...(data || []).map(toJS))
  }

  return { saved, duplicatesCollapsed: entries.length - deduped.length }
}
